"""
Offline endpoint-aligned robust piecewise-affine trend estimator.

The enhanced estimator uses self-dual multiscale morphology to remove
short-duration excursions and a bounded complexity-penalized affine
segmentation to obtain a low-reversal trend.  Output is aligned to endpoints
window_size - 1 through N - 1.
"""
import numpy as np

try:
    from scipy.ndimage import minimum_filter1d, maximum_filter1d
    from scipy.signal import savgol_filter
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def adaptive_filter(x, window_size=20):
    """Trailing-window moving-average baseline."""
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1:
        raise ValueError("window_size must be at least 1")
    if x.size < window_size:
        raise ValueError(
            f"Input signal length ({x.size}) must be >= window_size ({window_size})"
        )
    return np.mean(np.lib.stride_tricks.sliding_window_view(x, window_size), axis=1)


def _finite_signal(x):
    x = np.asarray(x, dtype=float).copy()
    good = np.isfinite(x)
    if not np.any(good):
        return np.zeros_like(x)
    if not np.all(good):
        ind = np.arange(x.size)
        x[~good] = np.interp(ind[~good], ind[good], x[good])
    return x


def _fallback_smoother(x, span):
    x = np.asarray(x, dtype=float)
    span = int(span)
    if span <= 1:
        return x.copy()
    kernel = np.ones(span, dtype=float) / float(span)
    left = span // 2
    right = span - 1 - left
    return np.convolve(
        np.pad(x, (left, right), mode="reflect"), kernel, mode="valid"
    )


def _morphology_scale(signal, radius):
    """Self-dual opening-closing morphology at one temporal scale."""
    signal = np.asarray(signal, dtype=float)
    radius = max(1, int(radius))
    size = 2 * radius + 1

    if _HAVE_SCIPY:
        eroded = minimum_filter1d(signal, size=size, mode="reflect")
        opened = maximum_filter1d(eroded, size=size, mode="reflect")
        dilated = maximum_filter1d(signal, size=size, mode="reflect")
        closed = minimum_filter1d(dilated, size=size, mode="reflect")
        co = minimum_filter1d(
            maximum_filter1d(opened, size=size, mode="reflect"),
            size=size,
            mode="reflect",
        )
        oc = maximum_filter1d(
            minimum_filter1d(closed, size=size, mode="reflect"),
            size=size,
            mode="reflect",
        )
        return 0.5 * (co + oc)

    padded = np.pad(signal, (radius, radius), mode="reflect")
    windows = np.lib.stride_tricks.sliding_window_view(padded, size)
    eroded = np.min(windows, axis=1)
    dilated = np.max(windows, axis=1)

    opened = np.max(
        np.lib.stride_tricks.sliding_window_view(
            np.pad(eroded, (radius, radius), mode="reflect"), size
        ),
        axis=1,
    )
    closed = np.min(
        np.lib.stride_tricks.sliding_window_view(
            np.pad(dilated, (radius, radius), mode="reflect"), size
        ),
        axis=1,
    )
    co = np.min(
        np.lib.stride_tricks.sliding_window_view(
            np.pad(opened, (radius, radius), mode="reflect"), size
        ),
        axis=1,
    )
    oc = np.max(
        np.lib.stride_tricks.sliding_window_view(
            np.pad(closed, (radius, radius), mode="reflect"), size
        ),
        axis=1,
    )
    return 0.5 * (co + oc)


def _piecewise_linear_filter(x, window_size):
    """Bounded dynamic-programming affine segmentation of a robust trend."""
    x = np.asarray(x, dtype=float)
    n = x.size
    if n <= 2:
        return x.copy()

    try:
        r1 = max(1, int(window_size) // 8)
        r2 = max(r1 + 1, int(window_size) // 4)
        y = 0.5 * (_morphology_scale(x, r1) + _morphology_scale(x, r2))
        y = _finite_signal(y)

        d = np.diff(x)
        dmed = float(np.median(d)) if d.size else 0.0
        sigma = float(np.median(np.abs(d - dmed)) / 0.6745)
        sigma = max(sigma, np.finfo(float).eps)
        beta = 3.2 * sigma * sigma * np.log(float(n) + 1.0)

        stride = max(1, int(np.ceil(float(n) / 600.0)))
        nodes = np.arange(0, n, stride, dtype=np.int64)
        if nodes.size == 0 or nodes[-1] != n - 1:
            nodes = np.r_[nodes, n - 1]
        nodes = np.unique(nodes)
        if nodes.size > 600:
            nodes = np.unique(np.r_[nodes[:599], n - 1])

        m = int(nodes.size)
        min_len = max(3, int(window_size) // 3)
        t = np.arange(n, dtype=float)

        py = np.r_[0.0, np.cumsum(y)]
        pty = np.r_[0.0, np.cumsum(t * y)]
        pt = np.r_[0.0, np.cumsum(t)]
        pt2 = np.r_[0.0, np.cumsum(t * t)]
        py2 = np.r_[0.0, np.cumsum(y * y)]

        def segment_cost(a, b):
            count = float(b - a + 1)
            st = pt[b + 1] - pt[a]
            st2 = pt2[b + 1] - pt2[a]
            sy = py[b + 1] - py[a]
            sty = pty[b + 1] - pty[a]
            sy2 = py2[b + 1] - py2[a]
            den = count * st2 - st * st
            if den <= np.finfo(float).eps:
                slope = 0.0
                intercept = sy / count
            else:
                slope = (count * sty - st * sy) / den
                intercept = (sy - slope * st) / count
            residual = sy2 - intercept * sy - slope * sty
            return max(0.0, float(residual)), float(intercept), float(slope)

        dp = np.full(m, np.inf, dtype=float)
        previous = np.full(m, -1, dtype=np.int64)
        dp[0] = -beta

        for j in range(1, m):
            end = int(nodes[j])
            for i in range(j):
                start = int(nodes[i])
                if end - start + 1 < min_len:
                    continue
                cost, _, _ = segment_cost(start, end)
                candidate = dp[i] + cost + beta
                if candidate < dp[j]:
                    dp[j] = candidate
                    previous[j] = i

        if not np.isfinite(dp[-1]):
            raise FloatingPointError("invalid dynamic-programming solution")

        segments = []
        j = m - 1
        while j > 0:
            i = int(previous[j])
            if i < 0:
                raise FloatingPointError("invalid predecessor")
            segments.append((int(nodes[i]), int(nodes[j])))
            j = i
        segments.reverse()

        fitted = np.empty(n, dtype=float)
        for k, (a, b) in enumerate(segments):
            _, intercept, slope = segment_cost(a, b)
            fitted[a:b + 1] = intercept + slope * t[a:b + 1]
            if k > 0:
                fitted[a] = 0.5 * (fitted[a] + fitted[a - 1])

        if not np.all(np.isfinite(fitted)):
            raise FloatingPointError("non-finite fit")

        centered_fit = fitted - np.median(fitted)
        fit_energy = float(np.dot(centered_fit, centered_fit))
        if fit_energy > np.finfo(float).eps:
            centered_data = y - np.median(y)
            gain = float(np.clip(
                np.dot(centered_fit, centered_data) / fit_energy, 0.85, 1.18
            ))
            fitted = gain * fitted + np.median(y - gain * fitted)

        return _finite_signal(fitted)

    except Exception:
        span = min(n if n % 2 else n - 1, max(3, int(window_size) | 1))
        if _HAVE_SCIPY and span >= 5:
            return np.asarray(
                savgol_filter(x, span, min(3, span - 1), mode="interp"),
                dtype=float,
            )
        return _fallback_smoother(x, max(1, span))


def enhanced_filter_with_trend_preservation(x, window_size=20):
    """Return robust full-batch trend estimates endpoint-aligned by suffix."""
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1:
        raise ValueError("window_size must be at least 1")
    if x.size < window_size:
        raise ValueError(
            f"Input signal length ({x.size}) must be >= window_size ({window_size})"
        )

    trend = _piecewise_linear_filter(_finite_signal(x), window_size)
    return _finite_signal(trend)[window_size - 1:]


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0.0, 10.0, length)
    clean_signal = (
        2.0 * np.sin(2.0 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2.0 * np.pi * 2.0 * t)
        + 0.5 * np.sin(2.0 * np.pi * 5.0 * t)
        + 0.8 * np.exp(-t / 5.0) * np.sin(2.0 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    return clean_signal + rng.normal(0.0, noise_level, length), clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is not None:
        delay = window_size - 1
        aligned_clean = clean_signal[delay:]
        aligned_noisy = np.asarray(noisy_signal, dtype=float)[delay:]
        m = min(filtered_signal.size, aligned_clean.size)

        filtered_signal = filtered_signal[:m]
        aligned_clean = aligned_clean[:m]
        aligned_noisy = aligned_noisy[:m]

        correlation = (
            float(np.corrcoef(filtered_signal, aligned_clean)[0, 1])
            if m > 1 and np.std(filtered_signal) > 0.0
            and np.std(aligned_clean) > 0.0
            else 0.0
        )
        noise_before = float(np.var(aligned_noisy - aligned_clean))
        noise_after = float(np.var(filtered_signal - aligned_clean))
        noise_reduction = (
            (noise_before - noise_after) / noise_before
            if noise_before > 0.0 else 0.0
        )
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": aligned_clean,
            "noisy_signal": aligned_noisy,
            "correlation": correlation,
            "noise_reduction": noise_reduction,
            "signal_length": m,
        }

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": None,
        "noisy_signal": None,
        "correlation": 0.0,
        "noise_reduction": 0.0,
        "signal_length": len(filtered_signal),
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")
